CREATE OR REPLACE FUNCTION public.raise_paper_review_defects() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.jobs; p jsonb; a uuid; k text; t text; BEGIN IF NEW.status <> 'submitted' OR NOT (NEW.responses ? '_paper_review_defects') THEN RETURN NEW; END IF; SELECT * INTO j FROM public.jobs WHERE id=NEW.job_id AND org_id=NEW.org_id; IF NOT FOUND OR NOT j.historic_backfill THEN RAISE EXCEPTION 'Paper defects require a completed paper-scan job'; END IF; IF auth.uid() IS NULL OR NOT public.has_role_in_org(auth.uid(),NEW.org_id,'admin') THEN RAISE EXCEPTION 'Only the company office can confirm paper defects'; END IF; a:=NULLIF(NEW.responses->>'riser_asset_id','')::uuid; IF a IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.assets WHERE id=a AND org_id=NEW.org_id AND site_id=j.site_id) THEN RAISE EXCEPTION 'Selected asset does not belong to this site'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(NEW.org_id::text||coalesce(a::text,j.site_id::text,j.id::text),0)); FOR p IN SELECT value FROM jsonb_array_elements(NEW.responses->'_paper_review_defects') LOOP k:=NULLIF(btrim(p->>'key'),''); t:=NULLIF(btrim(p->>'title'),''); CONTINUE WHEN k IS NULL OR t IS NULL; IF NOT EXISTS(SELECT 1 FROM public.defects d WHERE d.org_id=NEW.org_id AND d.site_id IS NOT DISTINCT FROM j.site_id AND d.asset_id IS NOT DISTINCT FROM a AND d.status NOT IN ('resolved','closed','cancelled') AND ((d.source_response_id=NEW.id AND d.source_key='paper:'||k) OR (a IS NOT NULL AND (d.source_key IN ('paper:'||k,'check:'||replace(k,'field:',''),'suggest:'||k) OR lower(regexp_replace(d.title,'[^a-zA-Z0-9]+','','g'))=lower(regexp_replace(t,'[^a-zA-Z0-9]+','','g')) OR (p->>'source_field_label' IS NOT NULL AND lower(regexp_replace(d.title,'^(Failed check: )','','i'))=lower(p->>'source_field_label')))))) THEN INSERT INTO public.defects(org_id,job_id,site_id,asset_id,reported_by,title,description,severity,status,category,location_on_site,source_response_id,source_key,source_kind,chargeable) VALUES(NEW.org_id,j.id,j.site_id,a,auth.uid(),left(t,200),p->>'description',CASE WHEN p->>'severity' IN ('low','medium','high','critical') THEN p->>'severity' ELSE 'medium' END,'open',coalesce(p->>'category','other'),NULLIF(p->>'location_on_site',''),NEW.id,'paper:'||k,'job',true) ON CONFLICT (source_response_id,source_key) WHERE source_response_id IS NOT NULL AND source_key IS NOT NULL DO NOTHING; END IF; END LOOP; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.raise_paper_review_defects() FROM PUBLIC,anon,authenticated; CREATE TRIGGER raise_paper_review_defects AFTER INSERT ON public.job_sheet_responses FOR EACH ROW EXECUTE FUNCTION public.raise_paper_review_defects();